import sys

def find_takeoff_time(n, s, landings):
    def time_diff(t1, t2):
        return (t2[0] * 60 + t2[1]) - (t1[0] * 60 + t1[1])

    if n == 0:
        return 0, 0

    # Check before first landing
    if time_diff((0, 0), landings[0]) >= s + 1:
        return 0, 0

    # Check between landings
    for i in range(n - 1):
        diff = time_diff(landings[i], landings[i + 1])
        if diff >= s * 2 + 2:
            minutes = (landings[i][0] * 60 + landings[i][1] + s) % 1440
            return divmod(minutes, 60)

    # Check after last landing
    last_landing = landings[-1]
    minutes = (last_landing[0] * 60 + last_landing[1] + s + 1) % 1440
    return divmod(minutes, 60)

def main():
    n, s = map(int, input().split())
    landings = [tuple(map(int, input().split())) for _ in range(n)]

    h, m = find_takeoff_time(n, s, landings)
