def find_earliest_takeoff(n, s, landings):
    # Convert landings to minutes from the start
    landings_in_minutes = [h * 60 + m for h, m in landings]

    # Start checking from the beginning of the day
    current_time = 0

    for i in range(n):
        # Calculate the safe landing time with space s on both sides
        if i == 0:
            # For the first landing, check from the start
            if current_time + s < landings_in_minutes[i]:
                return divmod(current_time, 60)
        else:
            # Check space between two landings
            if current_time + s < landings_in_minutes[i] - s:
                return divmod(current_time, 60)

        # Move to the next landing
        current_time = landings_in_minutes[i] + 1

    # If no suitable time is found between landings, insert at the end
    return divmod(current_time, 60)

