import sys

def find_takeoff_time(n, s, landings):
    # Convert landings to minutes since start
    landings_minutes = [h * 60 + m for h, m in landings]

    # Check for takeoff at the start
    if landings_minutes[0] - s >= 0:
        return 0, 0

    # Check between landings
    for i in range(1, n):
        if landings_minutes[i] - landings_minutes[i-1] >= 2 * s:
            minutes = landings_minutes[i-1] + s
            return minutes // 60, minutes % 60

    # Check after last landing
    last_landing = landings_minutes[-1]
    if last_landing + s * 2 <= 24 * 60:
        return (last_landing + s) // 60, (last_landing + s) % 60

    # No valid time found
    return -1, -1

def main():
    n, s = map(int, input().split())
    landings = [tuple(map(int, input().split())) for _ in range(n)]

    h, m = find_takeoff_time(n, s, landings)

    if h == -1:
        print("No valid time found")
    else:
        print(h, m)

if __name__ == "__main__":
    main()
